              .map(
                  bytes ->
                      BonsaiAccount.fromRLP(BonsaiWorldState.this, address, bytes, true, codeCache))
              .orElse(null);
      if (oldAccount == null) {
        // This is when an account is both created and deleted within the scope of the same
        // block. A not-uncommon DeFi bot pattern.
